export default function attempt({ previousState }) {
  const count = previousState === null ? 1 : previousState.count + 1;
  if (!Number.isSafeInteger(count) || count < 1 || count > 5)
    throw Error("Invalid Binance retry state");
  return { state: { count }, canRetry: count < 5 };
}

