export default function next({ chunks, previousState, lastMessage }) {
  if (
    !Array.isArray(chunks) ||
    chunks.some((x) => typeof x !== "string" || !x.length || x.length > 4000)
  )
    throw Error("Invalid Telegram chunks");
  let index = 0;
  if (previousState !== null) {
    if (
      !Number.isSafeInteger(previousState.index) ||
      previousState.index < 0 ||
      previousState.index >= chunks.length ||
      !lastMessage ||
      !Number.isSafeInteger(lastMessage.messageId) ||
      lastMessage.messageId <= 0
    )
      throw Error("Invalid Telegram result");
    index = previousState.index + 1;
  }
  return {
    state: { index },
    more: index < chunks.length,
    text: chunks[Math.min(index, chunks.length - 1)],
  };
}
